<template><PageShell title="Platform Audit Logs" subtitle="Review approval, organization, citizen, dispatch, and administrative actions across DASCARE." icon="lucide:history" eyebrow="Platform Executive"><section class="overflow-hidden rounded-3xl border border-base-300 bg-base-100 shadow-sm dark:border-white/10 dark:bg-[#071829]"><div class="flex gap-3 border-b border-base-300 p-4"><input v-model="search" class="min-w-0 flex-1 rounded-xl border border-base-300 bg-base-100 px-4 py-2.5 text-sm dark:bg-white/5 dark:text-white" placeholder="Search action, actor, organization..." @keyup.enter="load(1)"/><button class="rounded-xl border border-base-300 px-4 text-xs font-bold" @click="load(1)">Search</button></div><div v-if="loading" class="py-20 text-center text-sm text-slate-400">Loading audit activity...</div><div v-else-if="!items.length" class="py-20 text-center text-sm text-slate-400">No matching audit entries.</div><div v-else class="divide-y divide-base-300 dark:divide-white/5"><article v-for="i in items" :key="i.id" class="flex flex-wrap items-center justify-between gap-3 px-5 py-4"><div><p class="text-sm font-black text-slate-800 dark:text-white/75">{{ pretty(i.action) }}</p><p class="mt-1 text-xs text-slate-400">{{ i.actor_name||'System' }} · {{ i.organization_name||pretty(i.entity_type) }}</p></div><div class="text-right"><p class="text-xs font-bold text-slate-500">{{ format(i.created_at) }}</p><p class="mt-1 text-[.65rem] text-slate-400">{{ i.entity_type }} #{{ i.entity_id||'—' }}</p></div></article></div><div class="flex justify-between border-t border-base-300 p-4 text-xs text-slate-400"><span>{{ pagination.total||0 }} entries</span><div class="flex gap-2"><button class="rounded-lg border border-base-300 px-3 py-1.5 font-bold disabled:opacity-40" :disabled="pagination.page<=1" @click="load(pagination.page-1)">Previous</button><button class="rounded-lg border border-base-300 px-3 py-1.5 font-bold disabled:opacity-40" :disabled="pagination.page>=pagination.pages" @click="load(pagination.page+1)">Next</button></div></div></section></PageShell></template>
<script setup>import{onMounted,ref}from'vue';import PageShell from '@/components/management/PageShell.vue';import{fetchPlatformAudit}from'@/services/adminCompletion';const search=ref(''),items=ref([]),pagination=ref({page:1,pages:1,total:0}),loading=ref(false);const pretty=v=>String(v||'').replaceAll('.',' › ').replaceAll('_',' ');const format=v=>v?new Date(String(v).replace(' ','T')).toLocaleString():'—';async function load(page=1){loading.value=true;try{const d=await fetchPlatformAudit({search:search.value,page});items.value=d.items||[];pagination.value=d.pagination||pagination.value}finally{loading.value=false}}onMounted(()=>load())</script>
